select * from customer_shopping_behavior

--Q.1 What is the total revenue generated by male and female customers?--
select gender,sum(purchase_amount) as total_revenue from customer_shopping_behavior group by gender;

--Q.2. Which customers used discount but still spent more than the average purchase amount?--
select customer_id, purchase_amount, discount_applied
from customer_shopping_behavior where discount_applied='Yes' and purchase_amount>=(select AVG(purchase_amount) from customer_shopping_behavior);

--Q.3. Which are top 5 products with the highest average review rating?--
select top 5 item_purchased,round(avg(review_rating),2) as avergae_review_rating from customer_shopping_behavior
group by item_purchased
order by avg(review_rating) desc;

--Q4. Compare the average Purchase Amounts between Standard and Express Shipping?--
select shipping_type,avg(purchase_amount) as average_purchase_amount from customer_shopping_behavior where shipping_type in ('Express','Standard')  group by shipping_type;

--Q5. Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers.--
select count(customer_id) as total_customers,avg(purchase_amount) as average_spend,sum(purchase_amount) as total_spend,subscription_status
from customer_shopping_behavior 
group by subscription_status
order by total_customers,average_spend desc;

--Q6. Which 5 products have the highest percentage of purchases with discounts applied?
select top 5 item_purchased,
round(100*sum(case when discount_applied='Yes' then 1 else 0 end)/count(*),2) as percentage_of_purchase
from customer_shopping_behavior 
group by item_purchased
order by percentage_of_purchase desc;

--Q7. Segment customers into New, Returning, and Loyal based on their total number of previous purchases, and show the count of each segment.--
with customer_type as (
select customer_id, previous_purchases,
case when previous_purchases =1 then 'New'
when previous_purchases between 2 and 10 then 'Returning'
else 'Loyal'
end as customer_segment
from customer_shopping_behavior)
select customer_segment,count(*) as number_of_customers from customer_type group by customer_segment;

--Q8. What are the top 3 most purchased products within each category?--
with item_count as(
select category,item_purchased,count(customer_id) as number_of_items,
row_number() over(partition by category order by count(customer_id) desc) as item_rank
from customer_shopping_behavior group by category,item_purchased
)
select item_rank,number_of_items,category,item_purchased from item_count where item_rank<=3;

--Q9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
select count(customer_id) as number_of_customers,subscription_status from customer_shopping_behavior where previous_purchases>5 group by subscription_status;

--Q10. What is the revenue contribution of each age group?--
select sum(purchase_amount) as total_revenue, age_group from customer_shopping_behavior group by age_group order by total_revenue desc;